def generate_clave(nombre):
    stopwords = {"LICENCIATURA", "INGENIERIA", "EN", "DE", "Y", "LA", "EL", "LOS", "LAS", "A", "PARA", "CON", "E"}
    words = [w for w in nombre.upper().split() if w not in stopwords]
    if not words:
        return "SINCL"[:5]
    abbr = "".join(w[0] for w in words)
    if len(abbr) < 5:
        abbr = (abbr + words[0])[:5]
    return abbr[:5]


def fix_clave(apps, schema_editor):
    Carrera = apps.get_model("uh_core", "Carrera")
    used = set()
