        base = generate_clave(carrera.nombre)
        clave = base
        counter = 1
        while clave in used or Carrera.objects.filter(clave=clave).exclude(pk=carrera.pk).exists():
            clave = f"{base[:4]}{chr(ord('0') + counter)}" if counter < 10 else f"{base[:3]}{counter}"
            counter += 1
        carrera.clave = clave
        carrera.save()
        used.add(clave)


